"use strict";(globalThis.webpackChunkmy_website||=[]).push([[86447],{90442(e){e.exports=JSON.parse('{"slug":"a0","title":"a0","short":"The protocol parameter that controls how much a stake pool operator\'s pledge boosts that pool\'s rewards.","category":"consensus","aliases":["a0 parameter","Pledge Influence"],"mentalModel":null,"related":["pledge","rewards","stake-pool","k-parameter"],"sources":[],"link":null,"level":"advanced","body":"A network parameter that scales how strongly operator pledge influences reward distribution. A higher `a0` means pools with larger pledges earn proportionally more rewards than equally sized pools with low pledge; a lower `a0` flattens the difference and weights pools more by their total delegation.\\n\\n`a0` works together with `k` to shape stake pool incentives toward both decentralization and operator commitment."}')}}]);